let storageOK=true,state;try{state=JSON.parse(await readState('bapsang.v1')||'null');}catch{storageOK=false;}
if(!state||state.version!==1)state={version:1,prefs:clone(DEFAULT_PREFS),pantry:{},weeks:{},checked:{},saved:[],week:mondayKey()};
state.userRecipes??=[];state.cookbooks??=[];state.extraGroceries??={};
try{state.shopping=validateShopping(state.shopping);}catch{state.shopping=validateShopping();storageOK=false;}
try{const library=validateLibrary(state);state.userRecipes=library.userRecipes;state.cookbooks=library.cookbooks;}catch{storageOK=false;state.userRecipes=[];state.cookbooks=[];}
state.weeks??={};state.checked??={};state.saved??=[];state.week=state.week&&state.weeks[state.week]?state.week:mondayKey();
