let page='setup',step=0,draft={...clone(state.prefs),store:null,stores:[],adults:state.prefs.adults??Math.max(1,state.prefs.people||2),kids:state.prefs.kids??0,days:state.prefs.days||[0,1,2,3,4,5,6],diet:state.prefs.diet||'none',vibes:state.prefs.vibes||[],style:'balanced',dislikes:state.prefs.dislikes||[],pantry:state.onboardingRevision===2?clone(state.pantry):{},tools:state.prefs.tools||['stove','microwave','ricecooker']};
let error='',allergyCategory='all',allergySearch='',dislikeCategory='all',dislikeSearch='',pantryCategory='all',pantrySearch='',previewPlan=null,loadingStage=0,recipeId=null,recipeSlot=null,recipeReturn='week',servings=2,recipeTab='ingredients',convert=false,savedOnly=false;
let selectedDay=null,libraryFilter='all',librarySearch='',mealTarget=null,editorDraft=null,editorError='',pantryReturn='week';
const weekdays=['월','화','수','목','금','토','일'];
const shopIds=['emart','costco','lotte','nobrand','megafood','homeplus','gsfresh','ssgfood','traders','everyday','maxx','orga','coupang','kurly','ssg'];
