const VIBES=[['quick','빠르고 간편하게','20분 안에 뚝딱','bolt'],['onepan','한 팬 요리','설거지는 가볍게','pan'],['batch','한 번에 넉넉하게','같은 메뉴를 나눠서','layers'],['family','온 가족이 함께','맵지 않은 메뉴로','family'],['comfort','익숙한 집밥','뜨끈하고 든든하게','pot'],['fresh','가볍고 산뜻하게','신선한 채소 위주로','leaf'],['fiber','채소·곡물 듬뿍','두부, 곡물, 초록 채소','sprout'],['takeout','외식 메뉴를 집에서','배달 대신 한 그릇','takeout']];
function save(){return writeState('bapsang.v1',JSON.stringify(state)).catch(()=>{storageOK=false;toast('데이터를 저장하지 못했어요. 저장 공간을 확인해주세요.');});}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function catalog(){return [...R,...state.userRecipes];}
function currentPlan(){return state.weeks[state.week]||Array.from({length:7},()=>[]);}
function weekCost(){return groceryList().reduce((n,x)=>n+x.cost,0);}
function storeNames(){return (state.prefs.stores||[state.prefs.store]).map(id=>STORES.find(x=>x.id===id)?.name).filter(Boolean).join(' · ');}
function weekTitle(){const current=mondayKey();return state.week===current?'이번 주 식단':state.week===shiftWeek(current,1)?'다음 주 식단':state.week===shiftWeek(current,-1)?'지난주 식단':`${dateAt(state.week).getMonth()+1}월 ${dateAt(state.week).getDate()}일 주간 식단`;}
function recipeMeta(r){return `${r.time}분 · ${r.kcal===null?'영양 미입력':r.kcal+' kcal'}`;}
function groceryList(){return groceries(currentPlan(),state.pantry,state.prefs.people,catalog(),state.extraGroceries[state.week]||{}).filter(x=>x.need>0);}
function checked(){return state.checked[state.week]||{};}
function chosenStore(){return STORES.find(x=>x.id===(page==='setup'?draft.store:state.prefs.store));}
function prefs(){return {...draft,stores:[...draft.stores],people:draft.adults+draft.kids*.5,meals:Object.keys(MEALS).filter(m=>draft.meals.includes(m)),days:[...draft.days].sort((a,b)=>a-b)};}
function logo(){return '<span class="app-logo">밥<span>상</span></span>';}
function brandMark(id){const marks={emart:'<span class="emart"><i>e</i>mart</span>',costco:'<span class="costco">COSTCO<small>WHOLESALE</small></span>',lotte:'<span class="lotte">LOTTE<small>MART</small></span>',nobrand:'<span class="nobrand">No Brand<small>노브랜드</small></span>',megafood:'<span class="megafood">Homeplus<small>MEGA FOOD MARKET</small></span>',homeplus:'<span class="homeplus">Homeplus</span>',gsfresh:'<span class="gsfresh"><i>GS</i> THE FRESH</span>',ssgfood:'<span class="ssgfood">SSG<small>FOOD MARKET</small></span>',traders:'<span class="traders">TRADERS<small>WHOLESALE CLUB</small></span>',everyday:'<span class="everyday"><i>e</i>mart<small>everyday</small></span>',maxx:'<span class="maxx"><small>LOTTE MART</small>MAXX</span>',orga:'<span class="orga">ORGA<small>WHOLE FOODS</small></span>',coupang:'<span class="coupang"><i>c</i><i>o</i><i>u</i><i>p</i><i>a</i><i>n</i><i>g</i><small>로켓프레시</small></span>',kurly:'<span class="kurly">Kurly</span>',ssg:'<span class="ssg">SSG<span>.COM</span></span>'};return `<span class="shop-logo" aria-hidden="true">${marks[id]}</span>`;}
function applianceArt(id){const common='<defs><linearGradient id="a" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#b7b8b0"/><stop offset="1" stop-color="#6d7069"/></linearGradient><linearGradient id="b"><stop stop-color="#484b46"/><stop offset="1" stop-color="#777970"/></linearGradient></defs>';
const shapes={microwave:'<path d="m8 29 13-9h66l9 10-3 50H11Z" fill="url(#a)"/><path d="M11 32h81v46H11z" fill="#676a62"/><rect x="17" y="38" width="55" height="33" rx="2" fill="#383e36"/><path d="m22 42 45 1v25H22z" fill="#50574a"/><rect x="78" y="40" width="8" height="10" fill="#a1ac91"/><circle cx="82" cy="61" r="4" fill="#d0d0c3"/><path d="M15 80v4m72-4v4" stroke="#4e514a" stroke-width="4"/>',toaster:'<path d="M20 75V39c0-20 60-20 60 0v36q-30 10-60 0" fill="url(#a)"/><ellipse cx="50" cy="35" rx="27" ry="10" fill="#b0b1a6"/><path d="m34 32 26-1m-25 7 26-1" stroke="#444a40" stroke-width="5" stroke-linecap="round"/><path d="M71 44v18m0-8h13" stroke="#444a40" stroke-width="4"/><circle cx="75" cy="70" r="3" fill="#a9b699"/>',blender:'<path d="m35 17 5 42h22l5-42Z" fill="#d6ddd0" stroke="#adb5a4" stroke-width="2"/><path d="M34 15h34v5H34z" fill="#777f6d"/><path d="M65 26q20 0 5 24l-6 1" fill="none" stroke="#a6ae9b" stroke-width="4"/><path d="m37 59-6 27h39l-6-27z" fill="url(#a)"/><circle cx="50" cy="73" r="7" fill="#646e59"/><circle cx="50" cy="73" r="3" fill="#b7c69d"/>',airfryer:'<path d="M24 84q-7-10-6-36 0-30 32-30t32 30q1 26-6 36z" fill="url(#b)"/><ellipse cx="50" cy="31" rx="24" ry="9" fill="#70776a"/><rect x="33" y="35" width="34" height="18" rx="7" fill="#373e32"/><text x="50" y="48" font-size="8" text-anchor="middle" fill="#c2d4a8">180°</text><path d="M23 58h54m-27 0v18" stroke="#c3c4b6" stroke-width="4"/><path d="M42 72h16v8H42z" fill="#353c30"/>',stove:'<path d="m19 30 62 0 13 49H6Z" fill="url(#b)"/><g fill="none" stroke="#31382e" stroke-width="4"><ellipse cx="31" cy="45" rx="12" ry="7"/><ellipse cx="68" cy="45" rx="12" ry="7"/><ellipse cx="26" cy="65" rx="12" ry="7"/><ellipse cx="73" cy="65" rx="12" ry="7"/></g><g fill="#b7b8ac"><circle cx="43" cy="76" r="3"/><circle cx="52" cy="76" r="3"/><circle cx="61" cy="76" r="3"/></g>',slowcooker:'<path d="M20 42h60v35q-30 18-60 0z" fill="url(#a)"/><ellipse cx="50" cy="41" rx="31" ry="12" fill="#737b68"/><ellipse cx="50" cy="38" rx="26" ry="9" fill="#a8b09d"/><path d="M44 25h12v7H44zM12 44h9v9h-9zm67 0h9v9h-9z" fill="#505a45"/><rect x="36" y="64" width="28" height="12" rx="4" fill="#4e5d41"/>',ricecooker:'<path d="M20 44q0-18 30-18t30 18v33q-30 16-60 0z" fill="#d8d7cb"/><ellipse cx="50" cy="37" rx="29" ry="12" fill="#f1f0e5"/><path d="M37 26q0-10 26-1" fill="none" stroke="#b2b9a7" stroke-width="5"/><rect x="35" y="56" width="30" height="15" rx="4" fill="#859473"/><text x="50" y="67" font-size="7" fill="white" text-anchor="middle">취사</text>',oven:'<path d="M18 17h64v70H18z" fill="url(#a)"/><rect x="22" y="21" width="56" height="13" fill="#c3c6ba"/><g fill="#5d6752"><circle cx="32" cy="27" r="3"/><circle cx="44" cy="27" r="3"/><circle cx="56" cy="27" r="3"/><circle cx="68" cy="27" r="3"/></g><path d="M24 39h52v41H24z" fill="#3e4836"/><path d="M27 44h46" stroke="#c8cabd" stroke-width="3"/><path d="M29 50h42v24H29z" fill="#5e6a52"/>'};return `<svg class="appliance-art" viewBox="0 0 100 100" aria-hidden="true">${common}${shapes[id]}</svg>`;}
function tick(selected){return `<span class="selection-dot">${selected?icon('check'):''}</span>`;}
function header(){const inSetup=page==='setup';return `<header class="app-header"><button class="icon-button ${inSetup&&step===0?'invisible':''}" data-a="back" aria-label="이전 화면">${icon('back')}</button>${logo()}${inSetup?`<span class="step-counter">${step+1}/11</span>`:`<button class="icon-button" data-a="restart" aria-label="식단 다시 설정">${icon('settings')}</button>`}</header>${inSetup?`<div class="step-progress"><span style="width:${(step+1)/11*100}%"></span></div>`:''}`;}
function render(){document.documentElement.dataset.page=page;$('#app').innerHTML=`<div class="app-shell">${header()}${page==='setup'?setupPage():page==='loading'?loadingPage():page==='ready'?readyPage():page==='week'?weekPage():page==='shopping'?shoppingPage():page==='recipe'?recipePage():page==='pantry'?pantryPage():savedPage()}</div>`;}
function title(t,sub=''){return `<div class="screen-title"><h1>${t}</h1>${sub?`<p>${sub}</p>`:''}</div>`;}
function footer(label,action,disabled=false,secondary=''){return `<footer class="screen-footer">${secondary}${error?`<div class="form-error" role="alert">${esc(error)}</div>`:''}<button class="primary-button" data-a="${action}" ${disabled?'disabled':''}>${label}</button><div class="app-utility">${page==='setup'&&step===0&&currentPlan().flat().length?'<button data-a="resume">저장한 식단</button>':''}<button data-a="about">앱 정보 · 데이터 관리</button></div></footer>`;}
function setupPage(){let content='',heading='',sub='',label='다음 '+icon('arrow'),disabled=false;
if(step===0){heading='어디서 주로 장보세요?';sub='온라인 장보기도 함께, 최대 3곳까지 선택할 수 있어요.';content=`<div class="shop-grid">${shopIds.map(id=>{const s=STORES.find(x=>x.id===id),selected=draft.stores.includes(id);return `<button class="shop-card ${selected?'selected':''}" data-a="store" data-id="${id}" aria-pressed="${selected}" aria-label="${s.name}">${brandMark(id)}<span class="shop-name">${id==='coupang'?'쿠팡 로켓프레시':s.name}</span>${selected?tick(true):''}</button>`;}).join('')}</div>`;label=draft.stores.length?`${draft.stores.length}곳 선택 확인`:'마트 선택 확인';disabled=!draft.stores.length;}
if(step===1){heading='누가 함께 먹나요?';sub='우리 집 인원에 맞게 모든 재료의 양을 조절해요.';content=`<div class="household">${[['adults','성인','1인분 기준','user'],['kids','아이','성인 양의 ½인분','child']].map(([id,t,d,ic])=>`<div class="household-row"><span class="household-icon">${icon(ic)}</span><div><b>${t}</b><small>${d}</small></div><div class="counter"><button data-a="household" data-field="${id}" data-delta="-1" aria-label="${t} 줄이기" ${draft[id]===0?'disabled':''}>${icon('minus')}</button><strong>${draft[id]}</strong><button data-a="household" data-field="${id}" data-delta="1" aria-label="${t} 늘리기" ${draft[id]>=8?'disabled':''}>${icon('plus')}</button></div></div>`).join('')}<div class="portions-line"><span>한 끼에 준비할 양</span><strong>${amount(draft.adults+draft.kids*.5)}<small>인분</small></strong></div></div>`;disabled=draft.adults+draft.kids===0;}
if(step===2){heading='어떤 끼니를 준비할까요?';sub='매주 식단에 포함할 끼니를 모두 골라주세요.';content=`<div class="meal-options">${Object.entries(MEALS).map(([id,t],i)=>`<button class="meal-option meal-${id} ${draft.meals.includes(id)?'selected':''}" data-a="multi" data-field="meals" data-id="${id}" aria-pressed="${draft.meals.includes(id)}"><span class="meal-color">${['🌤️','☀️','🌙','🍎'][i]}</span><div><b>${t}</b><small>${['빠르고 가볍게 시작해요','도시락으로도 든든하게','하루의 메인 메뉴','끼니 사이 작은 즐거움'][i]}</small></div>${tick(draft.meals.includes(id))}</button>`).join('')}</div>`;disabled=!draft.meals.length;}
if(step===3){heading='어느 요일에 요리하세요?';sub='선택한 요일에만 식단을 준비할게요.';content=`<div class="days-screen"><div class="days-row">${weekdays.map((w,i)=>`<button class="day-option ${draft.days.includes(i)?'selected':''}" data-a="day" data-id="${i}" aria-pressed="${draft.days.includes(i)}"><b>${w}</b><span>${draft.days.includes(i)?icon('check'):''}</span></button>`).join('')}</div><p>${draft.days.length?`일주일에 ${draft.days.length}일 요리해요`:'하나 이상의 요일을 골라주세요'}</p></div>`;disabled=!draft.days.length;}
if(step===4){heading='주방에 어떤 도구가 있나요?';sub='가지고 있는 조리도구를 모두 눌러주세요. 만들 수 있는 요리만 추천해요.';content=`<div class="kitchen-scene">${Object.entries(TOOLS).map(([id,t])=>`<button class="appliance appliance-${id} ${draft.tools.includes(id)?'selected':''}" data-a="multi" data-field="tools" data-id="${id}" aria-pressed="${draft.tools.includes(id)}">${applianceArt(id)}<span>${t}</span></button>`).join('')}</div><p class="micro-note">밥 메뉴에는 가스·인덕션 또는 전기밥솥이 필요해요.</p>`;}
if(step===5){heading='어떤 방식으로 드시나요?';content=`<div class="diet-grid">${DIETS.map(([id,t,d,e])=>`<button class="option-card ${draft.diet===id?'selected':''}" data-a="diet" data-id="${id}" aria-pressed="${draft.diet===id}"><span class="option-emoji">${e}</span><b>${t}</b><small>${d}</small>${draft.diet===id?tick(true):''}</button>`).join('')}</div>`;}
if(step===6){heading='어떤 메뉴가 끌리세요?';content=`<div class="vibe-grid">${VIBES.map(([id,t,d,ic])=>`<button class="option-card ${draft.vibes.includes(id)?'selected':''}" data-a="multi" data-field="vibes" data-id="${id}" aria-pressed="${draft.vibes.includes(id)}">${icon(ic)}<b>${t}</b><small>${d}</small>${draft.vibes.includes(id)?tick(true):''}</button>`).join('')}</div>`;}
if(step===7){heading='알레르기가 있나요?';content=allergyPicker();label='확인하고 계속하기';}
if(step===8){heading='싫어하는 음식이 있나요?';content=dislikePicker();label=draft.dislikes.length?`${draft.dislikes.length}가지 제외하고 계속`:'지금은 건너뛰기';}
if(step===9){heading='이미 가지고 있는 재료는요?';content=pantryPicker();label=Object.values(draft.pantry).some(x=>x>0)?`계속하기 · ${Object.values(draft.pantry).filter(x=>x>0).length}가지 선택`:'지금은 건너뛰기';}
if(step===10){heading='일주일 장보기 예산';sub=`성인 ${draft.adults}명 · 아이 ${draft.kids}명 · ${draft.days.length}일 · 하루 ${draft.meals.length}끼 · 한 끼 ${amount(prefs().people)}인분`;content=budgetPage();label='식단 만들기 '+icon('arrow');}
return `<main class="screen setup-screen step-${step}">${title(heading,sub)}${content}${!storageOK?'<p class="micro-note">브라우저 저장 공간을 사용할 수 없어 변경 내용이 유지되지 않을 수 있어요.</p>':''}</main>${footer(label,step===10?'generate':'next',disabled)}`;}
function restrictionTools(kind,options,groups,selected,category,query){
 const field=kind==='allergy'?'allergies':'dislikes',name=kind==='allergy'?'알레르기':'기피 음식';
 return `<div class="restriction-tools"><label class="restriction-search" for="${kind}-search">${icon('search')}<input id="${kind}-search" value="${esc(query)}" placeholder="${kind==='allergy'?'키위, 복숭아, 견과류 등 검색':'고수, 깻잎, 가지 등 검색'}" aria-label="${name} 검색">${query?`<button type="button" data-a="restriction-clear-search" data-kind="${kind}" aria-label="검색어 지우기">${icon('close')}</button>`:''}</label><div class="restriction-categories" aria-label="${name} 분류">${groups.map(([id,t])=>`<button data-a="restriction-category" data-kind="${kind}" data-id="${id}" aria-pressed="${category===id}" class="${category===id?'active':''}">${t}</button>`).join('')}</div><div class="restriction-count"><span>${options.length}가지 중 <b>${selected.length}가지 선택</b></span>${selected.length?`<button data-a="restriction-reset" data-kind="${kind}">선택 초기화</button>`:'<span>여러 개 고를 수 있어요</span>'}</div>${selected.length?`<div class="restriction-selected" aria-label="선택한 ${name}">${selected.map(id=>{const x=options.find(o=>o.id===id);return x?`<button data-a="multi" data-field="${field}" data-id="${id}" aria-label="${esc(x.label)} 선택 해제">${x.emoji} ${esc(x.label)} ${icon('close')}</button>`:'';}).join('')}</div>`:''}</div>`;
}
function allergyPicker(){
 const options=ALLERGY_OPTIONS.filter(x=>(allergyCategory==='all'||x.group===allergyCategory)&&optionMatches(x,allergySearch));
 return restrictionTools('allergy',ALLERGY_OPTIONS,ALLERGY_GROUPS,draft.allergies,allergyCategory,allergySearch)+`<div class="allergy-grid">${!allergySearch&&allergyCategory==='all'?`<button class="option-card ${!draft.allergies.length?'selected':''}" data-a="no-allergy" aria-pressed="${!draft.allergies.length}">${icon('check')}<b>알레르기 없어요</b><small>특별히 피할 재료 없어요</small>${!draft.allergies.length?tick(true):''}</button>`:''}${options.map(x=>`<button class="option-card ${draft.allergies.includes(x.id)?'selected':''}" data-a="multi" data-field="allergies" data-id="${x.id}" aria-pressed="${draft.allergies.includes(x.id)}"><span class="allergen-emoji">${x.emoji}</span><b>${esc(x.label)}</b><small>식단에서 제외해요</small>${draft.allergies.includes(x.id)?tick(true):''}</button>`).join('')}</div>${!options.length?'<p class="restriction-empty">일치하는 항목이 없어요.<br>다른 이름으로 검색하거나 전체 목록을 살펴보세요.</p>':''}<p class="micro-note">선택한 알레르기 재료와 연결된 가공식품을 식단에서 제외해요. 실제 제품의 원재료와 교차접촉 가능성은 제품 라벨로 확인해주세요.</p>`;
}
function dislikePicker(){
 const options=DISLIKE_OPTIONS.filter(x=>(dislikeCategory==='all'||x.group===dislikeCategory)&&optionMatches(x,dislikeSearch));
 return restrictionTools('dislike',DISLIKE_OPTIONS,DISLIKE_GROUPS,draft.dislikes,dislikeCategory,dislikeSearch)+`<div class="dislike-chips">${options.map(x=>`<button class="dislike-chip ${draft.dislikes.includes(x.id)?'selected':''}" data-a="multi" data-field="dislikes" data-id="${x.id}" aria-pressed="${draft.dislikes.includes(x.id)}"><span>${x.emoji}</span>${esc(x.label)}${draft.dislikes.includes(x.id)?icon('close'):''}</button>`).join('')}</div>${!options.length?'<p class="restriction-empty">일치하는 항목이 없어요.<br>다른 이름으로 검색하거나 전체 목록을 살펴보세요.</p>':''}<p class="dislike-note">선택한 재료는 모든 식단과 메뉴 교체 후보에서 빼드릴게요. 버섯류·두부류·유제품 전체를 고르면 같은 종류의 재료도 함께 제외해요.</p>`;
}
function restrictionRender(){
 const active=document.activeElement,field=active?.dataset.field,id=active?.dataset.id,a=active?.dataset.a,y=scrollY;
 render();window.scrollTo(0,y);
 if(a&&field&&id){document.querySelector(`[data-a="${a}"][data-field="${field}"][data-id="${id}"]`)?.focus({preventScroll:true});}
}
function pantryPicker(){const ids=Object.keys(I).filter(id=>{const c=I[id].category;return (!pantrySearch||I[id].name.includes(pantrySearch))&&(pantryCategory==='all'||pantryCategory==='fresh'&&c==='채소·과일'||pantryCategory==='meat'&&['육류·달걀','생선·해산물'].includes(c)||pantryCategory==='fridge'&&c==='유제품·두부'||pantryCategory==='pantry'&&c==='곡물·양념');});return `<div class="pantry-search">${icon('search')}<input id="pantry-search" value="${esc(pantrySearch)}" placeholder="재료 찾기" aria-label="보유 재료 검색"></div><div class="pantry-categories">${[['all','전체'],['fresh','채소·과일'],['meat','고기·생선'],['fridge','냉장'],['pantry','곡물·양념']].map(([id,t])=>`<button class="${pantryCategory===id?'active':''}" data-a="pantry-category" data-id="${id}">${t}</button>`).join('')}</div><div class="pantry-picker">${ids.map(id=>`<div class="pantry-tile ${draft.pantry[id]>0?'selected':''}"><button class="pantry-pick" data-a="pantry" data-id="${id}" aria-pressed="${draft.pantry[id]>0}"><span>${I[id].emoji}</span><b>${I[id].name}</b>${draft.pantry[id]>0?tick(true):''}</button>${draft.pantry[id]>0?`<button class="pantry-amount" data-a="pantry-amount" data-id="${id}" aria-label="${I[id].name} 보유 수량 수정">${amount(draft.pantry[id])}${I[id].unit} <span>수정</span></button>`:''}</div>`).join('')}</div>${!ids.length?'<p class="empty-copy">일치하는 재료가 없어요.</p>':''}<p class="micro-note">처음 선택하면 1팩으로 계산해요. 선택한 재료의 수량을 눌러 수정할 수 있어요.</p>`;}
function budgetPage(){let estimate=null;try{previewPlan=makePlan(prefs(),draft.pantry,0,catalog());estimate=totalCost(previewPlan,draft.pantry,prefs().people,catalog());}catch(e){previewPlan=null;error=e.message;}const portions=draft.days.length*draft.meals.length*prefs().people;return `<div class="budget-screen"><div class="budget-input"><span>₩</span><input id="budget-input" inputmode="numeric" type="text" value="${draft.budget.toLocaleString('ko-KR')}" aria-label="일주일 장보기 예산"></div><p class="budget-caption">일주일 기준 · 금액을 눌러 직접 입력할 수 있어요</p><input class="budget-range" id="budget-range" type="range" min="10000" max="${Math.max(300000,draft.budget)}" step="1000" value="${draft.budget}" aria-label="예산 조절"><div class="range-labels"><span>1만원</span><span>${amount(Math.max(300000,draft.budget)/10000)}만원</span></div><div id="budget-status">${budgetStatus(estimate)}</div><div class="budget-metrics"><div><b id="weekly-budget">${won(draft.budget)}</b><span>주간 예산</span></div><div><b id="per-serving">${won(draft.budget/portions)}</b><span>1인분 예산</span></div><div><b>${amount(portions)}</b><span>주간 준비 인분</span></div></div><p class="micro-note">선택한 마트: ${chosenStore()?.name||''}<br>실시간 마트 가격이 아닌 공통 예시 단가예요. 조건과 포장 단위에 따라 예산을 초과할 수 있어요.</p>${error?'<button class="link-button" data-a="back">이전 설정으로 돌아가 조정하기</button>':''}</div>`;}
function budgetStatus(estimate){if(estimate===null)return '<div class="budget-alert warning">조건에 맞는 식단을 만들 수 없어요. 이전 설정을 확인해주세요.</div>';return `<div class="budget-alert ${estimate>draft.budget?'warning':''}">${icon(estimate>draft.budget?'info':'check')}<div><b>${estimate>draft.budget?'예산을 조금 더 살펴봐요':'예산 안에서 준비할 수 있어요'}</b><p>현재 조건의 장보기 예상 비용은 ${won(estimate)}${estimate>draft.budget?` · 예산보다 ${won(estimate-draft.budget)} 높아요`:''}</p></div></div>`;}
function updateBudget(n,source){draft.budget=Math.max(0,Math.min(1000000,n||0));if(source!=='input')$('#budget-input').value=draft.budget.toLocaleString('ko-KR');$('#budget-range').max=Math.max(300000,draft.budget);$('.range-labels span:last-child').textContent=amount(Math.max(300000,draft.budget)/10000)+'만원';if(source!=='range')$('#budget-range').value=draft.budget;$('#weekly-budget').textContent=won(draft.budget);$('#per-serving').textContent=won(draft.budget/(draft.days.length*draft.meals.length*prefs().people));$('#budget-status').innerHTML=budgetStatus(previewPlan?totalCost(previewPlan,draft.pantry,prefs().people,catalog()):null);}
function loadingPage(){const stages=['선택한 마트 확인하기','조건에 맞는 레시피 고르기','장보기 수량 계산하기','예산 확인하기','일주일 식단 마무리하기'];return `<main class="screen loading-screen"><div class="food-orbit"><span>🥑</span><span>🌽</span><span>🍅</span><span>🥕</span><span>🥦</span><span>🍓</span><span>🍋</span><div>🥦${logo()}</div></div><h1>${stages[Math.min(loadingStage,4)]}…</h1><div class="loading-stages">${stages.map((s,i)=>`<div class="${i<loadingStage?'complete':i===loadingStage?'current':''}"><span>${i<loadingStage?icon('check'):i===loadingStage?'<i class="spinner"></i>':'○'}</span>${s}…</div>`).join('')}</div></main>`;}
function foodThumb(r){return r.image&&!isBundledApp()?`<img src="assets/${r.image}.jpg" alt="${esc(r.name)} 상차림 예시">`:`<span class="food-thumb">${r.emoji}</span>`;}
function mealRows(plan,compact=false){return plan.map((slots,d)=>selectedDay!==null&&!compact&&page==='week'&&selectedDay!==d?'':`${!compact&&slots.length?`<h2 class="day-divider">${weekdays[d]}요일 <small>${dateAt(state.week,d).getMonth()+1}.${dateAt(state.week,d).getDate()}</small></h2>`:''}${slots.map((s,index)=>{const r=catalog().find(x=>x.id===s.recipe);return `<div class="recipe-row ${s.cooked?'cooked':''}"><button class="recipe-row-main" data-a="recipe" data-id="${r.id}" data-day="${d}" data-index="${index}">${foodThumb(r)}<div><small>${weekdays[d]}요일 · ${MEALS[s.meal]}${s.cooked?' · ✓ 완료':''}</small><b>${esc(r.name)}</b><span>${recipeMeta(r)}</span></div></button><button class="row-icon" data-a="swap" data-day="${d}" data-index="${index}" aria-label="${weekdays[d]}요일 ${MEALS[s.meal]} 메뉴 바꾸기">${icon('refresh')}</button></div>`;}).join('')}`).join('');}
function readyPage(){const p=currentPlan(),g=groceryList();return `<main class="screen result-screen">${title('일주일 식단이 준비됐어요!')}<div class="result-summary"><div><span>이번 주 식사</span><strong>${p.flat().length}</strong><small>이번 주 · ${chosenStore()?.name}</small></div><button data-a="shopping">${icon('cart')}<b>장보기 목록</b><small>${g.length}가지 재료</small></button></div><div class="compact-recipes">${mealRows(p,true)}</div><p class="micro-note">장보기 예상 ${won(totalCost(p,state.pantry,state.prefs.people,catalog()))} · 예시 단가${totalCost(p,state.pantry,state.prefs.people,catalog())>state.prefs.budget?' · 설정 예산 초과':''}</p></main>${footer('좋아요, 이 식단으로 시작 '+icon('arrow'),'accept')}`;}
function weekPage(){return weeklyView();}
function weekRange(){return `${dateAt(state.week).getMonth()+1}.${dateAt(state.week).getDate()} — ${dateAt(state.week,6).getMonth()+1}.${dateAt(state.week,6).getDate()}`;}
function shoppingPage(){return commerce.view();}
function recipePage(){const r=catalog().find(x=>x.id===recipeId),slot=recipeSlot?currentPlan()[recipeSlot.day]?.[recipeSlot.index]:null;return `<main class="recipe-screen"><div class="recipe-hero">${r.image&&!isBundledApp()?`<img src="assets/${r.image}.jpg" alt="${esc(r.name)} 상차림 예시">`:`<span>${r.emoji}</span>`}<small>${isBundledApp()?'메뉴 일러스트':'상차림 예시'}</small></div><div class="recipe-content">${title(r.name)}<div class="recipe-actions"><button class="${state.saved.includes(r.id)?'active':''}" data-a="bookmark">${icon('bookmark')}<span>${state.saved.includes(r.id)?'보관됨':'보관함'}</span></button><button data-a="week">${icon('calendar')}<span>식단</span></button><button data-a="shopping">${icon('cart')}<span>장보기</span></button><button data-a="share-recipe">${icon('share')}<span>공유</span></button></div>${r.id.startsWith('own-')?`<button class="outline-button" data-a="edit-recipe" data-id="${r.id}">레시피 수정</button>`:''}<button class="outline-button" data-a="recipe-books">${icon('layers')} 요리책에 담기</button><button class="outline-button" data-a="plan-recipe" data-id="${r.id}">${icon('plus')} 식단에 추가</button><h2 class="section-label">영양 정보 · 1인분 기준</h2><div class="nutrition"><div><b>${r.kcal??'—'}</b><span>kcal</span></div><div><b>${r.protein??'—'}<small>g</small></b><span>단백질</span></div><div><b>${r.carbs??'—'}<small>g</small></b><span>탄수화물</span></div><div><b>${r.fat??'—'}<small>g</small></b><span>지방</span></div></div><h2 class="section-label">레시피 노트</h2><p class="recipe-notes">조리 ${r.time}분 · ${r.tools.map(x=>TOOLS[x]).join(' · ')||'불 없이 만들어요'}<br>약 ${won(recipeCost(r))} / 1인분 · ${won(recipeCost(r,servings))} / ${amount(servings)}인분</p>${r.note?`<p class="micro-note">${esc(r.note)}</p>`:''}${r.sourceUrl?`<p class="micro-note">원본: <a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">레시피 출처 보기</a></p>`:''}${slot?`<button class="cooked-button ${slot.cooked?'active':''}" data-a="cooked">${icon('check')} ${slot.cooked?'요리 완료됨 · 취소하기':'요리 완료로 표시'}</button>`:''}<div class="recipe-tabs"><button class="${recipeTab==='ingredients'?'active':''}" data-a="recipe-tab" data-id="ingredients">준비 재료</button><button class="${recipeTab==='steps'?'active':''}" data-a="recipe-tab" data-id="steps">만드는 방법</button></div><div class="recipe-serving-row"><div class="servings"><button data-a="servings" data-delta="-1" aria-label="인분 줄이기">${icon('minus')}</button><b>${amount(servings)}<span>인분</span></b><button data-a="servings" data-delta="1" aria-label="인분 늘리기">${icon('plus')}</button></div><button class="convert-button" data-a="convert">${icon('refresh')} ${convert?'g·ml로 보기':'단위 바꾸기'}</button></div>${recipeTab==='ingredients'?`<div class="ingredient-list">${Object.entries(r.ing).map(([id,q])=>`<div><span>${I[id].emoji}</span><p><b>${quantity(q*servings,I[id].unit)}</b> ${I[id].name}</p></div>`).join('')}</div>`:`<ol class="recipe-steps">${r.steps.map((s,i)=>`<li><span>${i+1}</span><p>${esc(s)}</p></li>`).join('')}</ol>`}<p class="micro-note">영양 정보와 재료 가격은 추정치예요. 밥 짓는 시간은 별도예요.<br>포함 알레르기: ${allergens(r).map(x=>ALLERGENS[x]).join(', ')||'등록된 주요 알레르기 없음'}. 실제 제품 라벨과 교차접촉 가능성은 별도로 확인해주세요.</p></div></main>`;}
function quantity(n,u){if(convert&&u==='g')return `${Number((n/1000).toFixed(4)).toLocaleString('ko-KR')}kg`;if(convert&&u==='ml')return `${Number((n/1000).toFixed(4)).toLocaleString('ko-KR')}L`;return `${amount(n)}${u}`;}
function savedPage(){return libraryView();}
function resetSetup(){draft={...clone(state.prefs),store:state.prefs.store,stores:[...(state.prefs.stores||[state.prefs.store])],adults:state.prefs.adults??state.prefs.people,kids:state.prefs.kids??0,days:state.prefs.days||[0,1,2,3,4,5,6],diet:state.prefs.diet||'none',vibes:state.prefs.vibes||[],dislikes:state.prefs.dislikes||[],pantry:clone(state.pantry)};page='setup';step=0;error='';render();scrollTop();}
function scrollTop(){window.scrollTo({top:0});}
function goNext(){error='';if(step===0&&!draft.store)return;if(step===1&&draft.adults+draft.kids===0)return;if(step===2&&!draft.meals.length)return;if(step===3&&!draft.days.length)return;step++;render();scrollTop();}
async function generate(){if(!Number.isFinite(draft.budget)||draft.budget<10000||draft.budget>1000000){error='예산을 10,000원부터 1,000,000원 사이로 입력해주세요.';render();return;}let next;try{next=makePlan(prefs(),draft.pantry,Date.now()%997,catalog());}catch(e){error=e.message;render();return;}error='';page='loading';loadingStage=0;render();scrollTop();for(let i=1;i<5;i++){await new Promise(r=>setTimeout(r,280));loadingStage=i;render();}state.prefs=prefs();delete state.prefs.pantry;state.pantry=clone(draft.pantry);state.week=mondayKey();state.weeks[state.week]=next;state.checked[state.week]={};state.onboardingRevision=2;state.accepted=false;await save();await new Promise(r=>setTimeout(r,220));page='ready';render();scrollTop();}
function back(){error='';if(page==='setup'){if(step>0){step--;render();scrollTop();}return;}if(page==='loading')return;if(page==='recipe'){page=recipeReturn;}else if(page==='shopping'||page==='saved'||page==='pantry'){page=state.accepted?'week':'ready';}else if(page==='ready'){page='setup';step=10;}else if(page==='week'){page='ready';}render();scrollTop();}
function textList(){return commerce.textList();}
async function download(text=textList(),name=`밥상-장보기-${state.week}.txt`){return exportText(name,text);}
async function copyText(text){try{await clipboard(text);toast('복사했어요.');}catch{openDialog(`<h2>텍스트 복사</h2><textarea id="copy-text" readonly>${esc(text)}</textarea><button class="primary-button" data-a="close-dialog">닫기</button>`);$('#copy-text').select();}}
let importedState=null;
async function about(){
 let info={name:'밥상',version:'1.0.0'};try{info=await (await fetch('release-public.json')).json();}catch{}
 openDialog(`<h2>밥상 <small class="app-version">${esc(info.version)}</small></h2><p>나를 위한 일주일, 밥상.<br>${isNativeApp()?'설정과 식단은 기기의 앱 저장 공간에 보관해요.':'설정과 식단은 이 브라우저에 보관해요.'}</p><div class="about-actions"><button data-a="policy" data-id="privacy">개인정보처리방침 ${icon('arrow')}</button><button data-a="policy" data-id="support">도움말 · 이용 안내 ${icon('arrow')}</button><button data-a="policy" data-id="licenses">오픈소스 안내 ${icon('arrow')}</button><button data-a="backup">데이터 백업 ${icon('download')}</button><button data-a="import">백업 파일 가져오기 ${icon('arrow')}</button><button class="danger-action" data-a="confirm-delete">모든 데이터 삭제 ${icon('close')}</button></div><input id="import-backup" type="file" accept="application/json,.json" hidden><p class="micro-note">백업 파일에는 알레르기 등 개인 설정이 포함돼요. 저장할 위치와 공유할 대상을 직접 선택해주세요.<br>장보기에서 연결된 상품의 가격 확인 시각과 적용 조건을 확인해주세요. 상품 열기만으로 쇼핑몰 장바구니에 담기지는 않아요. 알레르기는 실제 제품의 원재료와 교차접촉 가능성을 별도로 확인해주세요.</p>${info.publisherName?`<p class="micro-note">운영: ${esc(info.publisherName)}${info.supportEmail?`<br>문의: <a href="mailto:${esc(info.supportEmail)}">${esc(info.supportEmail)}</a>`:''}</p>`:''}`);
}
async function showPolicy(id){const path=id==='privacy'?'privacy.html':id==='licenses'?'open-source.html':'support.html';const response=await fetch(path);if(!response.ok)throw new Error('안내를 불러오지 못했어요.');const html=new DOMParser().parseFromString(await response.text(),'text/html');openDialog(`<div class="legal-copy">${html.querySelector('main').innerHTML}</div><button class="primary-button" data-a="about">앱 정보로 돌아가기</button>`);}
let lastFocus=null;
function openDialog(html){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-label="앱 안내 및 데이터 관리"><button class="dialog-close icon-button" data-a="close-dialog" aria-label="닫기">${icon('close')}</button>${html}</section></div>`;document.body.classList.add('dialog-open');$('.dialog input,.dialog textarea,.dialog button')?.focus();}
function closeDialog(){$('#modal-root').innerHTML='';document.body.classList.remove('dialog-open');lastFocus?.focus();}
function bottomNav(){return `<nav class="bottom-nav" aria-label="주요 메뉴">${[['week','calendar','식단'],['pantry-open','leaf','냉장고'],['saved','bookmark','레시피'],['shopping','cart','장보기']].map(([a,ic,label])=>`<button data-a="${a}" class="${(a==='pantry-open'&&page==='pantry')||(a==='saved'&&page==='saved')||a===page?'active':''}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav>`;}
function budgetCard(){const cost=weekCost(),difference=state.prefs.budget-cost;return `<section class="week-budget"><span>${storeNames()} · 공통 예시 단가</span><div><strong>${won(cost)}</strong><small>${difference>=0?'예산보다 '+won(difference)+' 여유':'예산보다 '+won(-difference)+' 초과'}</small></div><div class="budget-meter"><span style="width:${Math.min(100,cost/state.prefs.budget*100)}%" class="${difference<0?'over':''}"></span></div><p>주간 예산 ${won(state.prefs.budget)} · 배송비·실시간 할인 제외</p></section>`;}
function weeklyView(){
 const plan=currentPlan(),exists=Boolean(state.weeks[state.week]),meals=Object.keys(MEALS).filter(m=>state.prefs.meals.includes(m)||plan.flat().some(s=>s.meal===m));
 return `<main class="screen result-screen">${title(weekTitle(),`${weekRange()} · ${amount(state.prefs.people)}인분`)}<div class="week-controls"><button data-a="week-shift" data-offset="-1" aria-label="지난주">${icon('back')}</button><button data-a="week-today">이번 주</button><button data-a="week-shift" data-offset="1">다음 주 ${icon('arrow')}</button></div><div class="week-grid" role="group" aria-label="일주일 식단표"><div class="grid-corner">끼니</div>${weekdays.map((w,d)=>`<button data-a="select-day" data-day="${d}" class="grid-day ${selectedDay===d?'active':''}" aria-pressed="${selectedDay===d}"><span>${w}</span><b>${dateAt(state.week,d).getDate()}</b></button>`).join('')}${meals.map(m=>`<span class="grid-meal-label">${MEALS[m]}</span>${plan.map((slots,d)=>{const s=slots.find(x=>x.meal===m),r=s&&catalog().find(x=>x.id===s.recipe);return `<button data-a="choose-slot" data-day="${d}" data-meal="${m}" class="grid-slot ${s?.cooked?'cooked':''}" aria-label="${weekdays[d]}요일 ${MEALS[m]} ${r?esc(r.name)+' 변경':'추가'}">${r?`<span>${r.emoji}</span>${s.cooked?'<i>✓</i>':''}`:icon('plus')}</button>`;}).join('')}`).join('')}</div><div class="week-view-options"><button data-a="select-day" data-day="all" class="${selectedDay===null?'active':''}">전체 보기</button><button data-a="week-generate">${icon('refresh')} ${exists?'주간 식단 다시 만들기':'이 주 식단 만들기'}</button></div>${budgetCard()}${!exists?`<div class="empty-copy">아직 이 주의 식단이 없어요.<br>위의 빈칸에서 메뉴를 고르거나<br>저장한 설정으로 한 주를 만들어보세요.</div>`:mealRows(plan)}<button class="outline-button wide" data-a="add-slot">${icon('plus')} 원하는 끼니 추가</button><p class="micro-note">표의 메뉴를 누르면 직접 교체할 수 있어요. 알레르기·기피 재료 설정은 유지돼요.<br>영양 정보는 1인분 기준 추정치예요. 요리 완료 표시는 냉장고 수량을 자동 차감하지 않아요.</p></main>${bottomNav()}`;
}
function libraryView(){
 const book=state.cookbooks.find(b=>b.id===libraryFilter);
 let recipes=catalog().filter(r=>libraryFilter==='favorites'?state.saved.includes(r.id):libraryFilter==='own'?r.id.startsWith('own-'):book?book.recipes.includes(r.id):true);
 if(mealTarget)recipes=recipes.filter(r=>r.meals.includes(mealTarget.meal)&&allowed(r,state.prefs,mealTarget.meal));
 recipes=recipes.filter(r=>!librarySearch||r.name.includes(librarySearch)||Object.keys(r.ing).some(id=>I[id].name.includes(librarySearch)));
 return `<main class="screen library-screen">${title(mealTarget?`${weekdays[mealTarget.day]}요일 ${MEALS[mealTarget.meal]} 고르기`:'나의 레시피',mealTarget?'알레르기·기피 재료·조리도구 조건에 맞는 메뉴만 보여요.':'마음에 드는 요리를 한곳에 모아두세요.')}<div class="library-tools"><button class="outline-button" data-a="new-recipe">${icon('plus')} 직접 등록</button><button class="outline-button" data-a="import-recipe">${icon('download')} 가져오기</button><button class="outline-button" data-a="new-book">${icon('layers')} 요리책</button></div><div class="pantry-search">${icon('search')}<input id="library-search" value="${esc(librarySearch)}" placeholder="레시피 또는 재료 검색" aria-label="레시피 검색"></div><div class="library-filters">${[['all','전체'],['favorites','즐겨찾기'],['own','직접 등록'],...state.cookbooks.map(b=>[b.id,b.name])].map(([id,name])=>`<button data-a="library-filter" data-id="${id}" class="${libraryFilter===id?'active':''}">${esc(name)}</button>`).join('')}</div>${book?`<button class="link-button" data-a="delete-book" data-id="${book.id}">이 요리책 삭제</button>`:''}<p class="library-count">${recipes.length}개 레시피</p><div class="library-grid">${recipes.map(r=>`<article class="library-card"><button data-a="${mealTarget?'place-meal':'recipe'}" data-id="${r.id}">${foodThumb(r)}<b>${esc(r.name)}</b><span>${recipeMeta(r)}</span><small>${won(recipeCost(r))} / 1인분</small></button><button class="library-save ${state.saved.includes(r.id)?'active':''}" data-a="library-bookmark" data-id="${r.id}" aria-label="${esc(r.name)} 즐겨찾기" aria-pressed="${state.saved.includes(r.id)}">${icon('bookmark')}</button></article>`).join('')}</div>${!recipes.length?'<p class="empty-copy">조건에 맞는 레시피가 없어요.<br>검색어나 요리책을 바꿔보세요.</p>':''}${mealTarget?`<button class="outline-button wide" data-a="cancel-pick">식단으로 돌아가기</button>${currentPlan()[mealTarget.day].some(s=>s.meal===mealTarget.meal)?'<button class="link-button" data-a="remove-slot">이 끼니 비우기</button>':''}`:''}<p class="micro-note">직접 등록한 레시피는 재료·수량을 확인한 뒤 저장해요. 영양 정보를 입력하지 않은 레시피는 저탄수·고단백 추천에서 제외해요.</p></main>${bottomNav()}`;
}
function pantryPage(){return `<main class="screen">${title('우리 집 냉장고','지금 가진 재료를 수정하면 장보기 목록에 반영돼요.')}<p class="pantry-summary">보유 재료 ${Object.values(draft.pantry).filter(q=>q>0).length}가지</p>${pantryPicker()}<button class="link-button" data-a="pantry-cancel">변경 취소</button></main>${footer('냉장고 저장 · 장보기 업데이트','pantry-save')}${bottomNav()}`;}
function editRecipe(recipe=null,values=null){
 editorDraft=values||{id:recipe?.id||'own-'+crypto.randomUUID(),name:recipe?.name||'',servings:1,time:recipe?.time||20,sourceUrl:recipe?.sourceUrl||'',ingredientText:recipe?Object.entries(recipe.ing).map(([id,q])=>`${I[id].name} ${Number(q.toFixed(3))}${I[id].unit}`).join('\n'):'',stepsText:recipe?.steps.join('\n')||'',meals:recipe?.meals||['lunch','dinner'],tools:recipe?.tools||['stove'],kcal:recipe?.kcal??'',protein:recipe?.protein??'',carbs:recipe?.carbs??'',fat:recipe?.fat??''};
 editorError='';renderRecipeEditor();
}
function renderRecipeEditor(){const d=editorDraft;openDialog(`<h2>${state.userRecipes.some(r=>r.id===d.id)?'레시피 수정':'레시피 등록'}</h2><form id="recipe-editor" class="editor-form"><label>요리 이름<input name="name" value="${esc(d.name)}" maxlength="100" required></label><div class="editor-pair"><label>아래 재료의 기준 인분<input name="servings" type="number" min="0.5" max="16" step="0.5" value="${esc(d.servings)}" required></label><label>조리 시간 (분)<input name="time" type="number" min="1" max="1440" value="${esc(d.time)}" required></label></div><label>재료와 수량 · 한 줄에 하나<textarea name="ingredientText" rows="7" required placeholder="달걀 2개&#10;쌀 170g&#10;간장 10ml">${esc(d.ingredientText)}</textarea></label><p class="micro-note">재료 이름과 단위를 아래 목록에 맞춰주세요. 수량을 임의로 추정하지 않아요. 등록한 인분으로 나눠 1인분을 계산해요.</p><details><summary>등록 가능한 재료 · 단위 보기</summary><div class="ingredient-reference">${Object.values(I).map(i=>`${i.name} (${i.unit})`).join(' · ')}</div></details><label>만드는 방법 · 한 줄에 한 단계<textarea name="stepsText" rows="5" required>${esc(d.stepsText)}</textarea></label><fieldset><legend>이 요리를 먹는 끼니</legend>${Object.entries(MEALS).map(([id,name])=>`<label class="inline-check"><input type="checkbox" name="meals" value="${id}" ${d.meals.includes(id)?'checked':''}>${name}</label>`).join('')}</fieldset><fieldset><legend>필요한 조리도구 · 불 없이 만들면 선택 해제</legend>${Object.entries(TOOLS).map(([id,name])=>`<label class="inline-check"><input type="checkbox" name="tools" value="${id}" ${d.tools.includes(id)?'checked':''}>${name}</label>`).join('')}</fieldset><label>원본 링크 (선택)<input name="sourceUrl" type="url" value="${esc(d.sourceUrl)}" placeholder="https://"></label><details><summary>영양 정보 입력 · 1인분 기준 (선택)</summary><div class="editor-pair">${[['kcal','열량 (kcal)'],['protein','단백질 (g)'],['carbs','탄수화물 (g)'],['fat','지방 (g)']].map(([id,name])=>`<label>${name}<input name="${id}" type="number" min="0" max="10000" step="any" value="${esc(d[id])}"></label>`).join('')}</div></details>${editorError?`<p class="form-error" role="alert">${esc(editorError)}</p>`:''}<button type="submit" class="primary-button">재료 확인하고 저장</button>${state.userRecipes.some(r=>r.id===d.id)?`<button type="button" class="link-button danger-action" data-a="delete-recipe" data-id="${d.id}">직접 등록한 레시피 삭제</button>`:''}</form>`);}
function slotDialog(recipe=null){openDialog(`<h2>${recipe?'식단에 추가':'어떤 끼니를 고를까요?'}</h2><p>${weekRange()}${recipe?' · '+esc(recipe.name):''}</p><form id="slot-form" class="editor-form" data-recipe="${recipe?.id||''}"><label>요일<select name="day">${weekdays.map((w,i)=>`<option value="${i}">${w}요일</option>`).join('')}</select></label><label>끼니<select name="meal">${Object.entries(MEALS).filter(([id])=>!recipe||recipe.meals.includes(id)).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><button type="submit" class="primary-button">${recipe?'이 끼니에 추가':'메뉴 고르기'}</button></form>`);}
function openRecipeImport(){openDialog(`<h2>레시피 가져오기</h2><p>웹페이지의 레시피나 SNS 게시물의 재료·만드는 법을 붙여넣어주세요. 가져온 내용은 직접 확인한 뒤 저장해요.</p><form id="recipe-import-form" class="editor-form"><label>원본 링크 (선택)<input id="recipe-source-url" name="sourceUrl" type="url" placeholder="https://"></label><button type="button" class="outline-button" data-a="read-recipe-link">링크에서 레시피 읽기</button><p id="recipe-import-status" class="micro-note" role="status">구조화된 레시피가 있는 공개 페이지를 지원해요. 로그인이 필요한 SNS 영상은 게시물의 내용을 복사해 붙여넣어주세요.</p><label>레시피 내용<textarea name="text" rows="10" placeholder="달걀 덮밥&#10;재료&#10;달걀 2개&#10;쌀 85g&#10;만드는 방법&#10;1. 쌀로 밥을 지어요.&#10;2. 달걀을 익혀 밥 위에 올려요." required></textarea></label><button type="submit" class="primary-button">내용 확인하기</button></form>`);}
async function featureAction(el){
 const a=el.dataset.a,id=el.dataset.id;
 if(a==='week-shift'||a==='week-today'){state.week=a==='week-today'?mondayKey():shiftWeek(state.week,Number(el.dataset.offset));selectedDay=null;save();render();scrollTop();return true;}
 if(a==='select-day'){selectedDay=el.dataset.day==='all'?null:Number(el.dataset.day);render();return true;}
 if(a==='week-generate'){if(state.weeks[state.week])openDialog(`<h2>이 주의 식단을 다시 만들까요?</h2><p>${weekRange()} 식단과 장보기 완료 표시를 새로 만들어요. 다른 주의 식단은 그대로 보관해요.</p><button class="primary-button" data-a="week-generate-confirm">새 식단 만들기</button><button class="cancel-button" data-a="close-dialog">취소</button>`);else await generateSavedWeek();return true;}
 if(a==='week-generate-confirm'){await generateSavedWeek();return true;}
 if(a==='choose-slot'){mealTarget={day:Number(el.dataset.day),meal:el.dataset.meal};libraryFilter='all';librarySearch='';page='saved';render();scrollTop();return true;}
 if(a==='place-meal'){state.weeks[state.week]=setMeal(currentPlan(),mealTarget.day,mealTarget.meal,id,state.prefs,catalog());state.checked[state.week]={};mealTarget=null;state.accepted=true;page='week';await save();render();scrollTop();toast('끼니와 장보기 목록에 반영했어요.');return true;}
 if(a==='remove-slot'){state.weeks[state.week]=currentPlan().map((day,d)=>d===mealTarget.day?day.filter(s=>s.meal!==mealTarget.meal):day);state.checked[state.week]={};mealTarget=null;await save();page='week';render();scrollTop();toast('끼니를 비웠어요.');return true;}
 if(a==='cancel-pick'){mealTarget=null;page='week';render();scrollTop();return true;}
 if(a==='add-slot'){slotDialog();return true;}
 if(a==='plan-recipe'){slotDialog(catalog().find(r=>r.id===id));return true;}
 if(a==='library-filter'){libraryFilter=id;render();return true;}
 if(a==='library-bookmark'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];await save();const y=scrollY;render();window.scrollTo(0,y);return true;}
 if(a==='new-recipe'||a==='edit-recipe'){editRecipe(a==='edit-recipe'?state.userRecipes.find(r=>r.id===id):null);return true;}
 if(a==='import-recipe'){openRecipeImport();return true;}
 if(a==='read-recipe-link'){
  const status=$('#recipe-import-status');status.textContent='공개 페이지에서 레시피를 읽고 있어요…';el.disabled=true;
  try{const url=publicRecipeUrl($('#recipe-source-url').value.trim());if(!url)throw new Error('원본 레시피 링크를 먼저 입력해주세요.');const html=await fetchRecipePage(url),doc=new DOMParser().parseFromString(html,'text/html'),objects=[];for(const script of doc.querySelectorAll('script[type="application/ld+json"]'))try{objects.push(JSON.parse(script.textContent));}catch{}
   const parsed=recipeFromStructuredData(objects);editRecipe(null,{id:'own-'+crypto.randomUUID(),servings:1,time:20,meals:['lunch','dinner'],tools:['stove'],kcal:'',protein:'',carbs:'',fat:'',...parsed,sourceUrl:url});
  }catch(e){if(status.isConnected)status.textContent=e.message||'이 링크를 읽지 못했어요. 레시피 내용을 붙여넣어주세요.';}finally{el.disabled=false;}return true;
 }
 if(a==='new-book'){openDialog('<h2>요리책 만들기</h2><form id="book-form" class="editor-form"><label>요리책 이름<input name="name" maxlength="60" placeholder="예: 15분 저녁" required></label><button class="primary-button" type="submit">요리책 만들기</button></form>');return true;}
 if(a==='recipe-books'){openDialog(`<h2>요리책에 담기</h2><div class="book-options">${state.cookbooks.map(b=>`<button data-a="toggle-book-recipe" data-id="${b.id}" aria-pressed="${b.recipes.includes(recipeId)}">${icon(b.recipes.includes(recipeId)?'check':'plus')} ${esc(b.name)}</button>`).join('')||'<p>먼저 나만의 요리책을 만들어주세요.</p>'}</div><button class="outline-button wide" data-a="new-book">${icon('plus')} 새 요리책</button>`);return true;}
 if(a==='toggle-book-recipe'){const book=state.cookbooks.find(b=>b.id===id);book.recipes=book.recipes.includes(recipeId)?book.recipes.filter(x=>x!==recipeId):[...book.recipes,recipeId];await save();await featureAction({dataset:{a:'recipe-books'}});return true;}
 if(a==='delete-book'){openDialog(`<h2>이 요리책을 삭제할까요?</h2><p>요리책에 담긴 레시피는 삭제하지 않아요.</p><button class="primary-button danger-button" data-a="delete-book-confirm" data-id="${id}">요리책 삭제</button>`);return true;}
 if(a==='delete-book-confirm'){state.cookbooks=state.cookbooks.filter(b=>b.id!==id);libraryFilter='all';await save();closeDialog();render();return true;}
 if(a==='delete-recipe'){openDialog(`<h2>이 레시피를 삭제할까요?</h2><p>이 레시피를 담은 주간 식단의 끼니와 요리책에서도 삭제해요.</p><button class="primary-button danger-button" data-a="delete-recipe-confirm" data-id="${id}">레시피 삭제</button>`);return true;}
 if(a==='delete-recipe-confirm'){state.userRecipes=state.userRecipes.filter(r=>r.id!==id);state.saved=state.saved.filter(x=>x!==id);for(const b of state.cookbooks)b.recipes=b.recipes.filter(x=>x!==id);for(const [key,plan]of Object.entries(state.weeks)){if(plan.flat().some(s=>s.recipe===id)){state.weeks[key]=plan.map(day=>day.filter(s=>s.recipe!==id));state.checked[key]={};}}await save();closeDialog();page='saved';mealTarget=null;render();toast('레시피를 삭제했어요.');return true;}
 if(a==='pantry-open'){pantryReturn=page==='recipe'?'week':page;draft.pantry=clone(state.pantry);pantrySearch='';pantryCategory='all';page='pantry';render();scrollTop();return true;}
 if(a==='pantry-save'){state.pantry=clone(draft.pantry);state.checked[state.week]={};await save();page=pantryReturn;render();scrollTop();toast('냉장고와 장보기 목록을 업데이트했어요.');return true;}
 if(a==='pantry-cancel'){draft.pantry=clone(state.pantry);page=pantryReturn;render();return true;}
 if(a==='extra-grocery'){openDialog(`<h2>장볼 재료 추가</h2><p>식단 외에 필요한 재료도 함께 장봐요. 냉장고 보유량은 합산 뒤 차감해요.</p><form id="extra-grocery-form" class="editor-form"><label>재료<input name="ingredient" list="ingredient-options" required></label>${ingredientOptions()}<label>수량 · 선택한 재료의 단위 기준<input name="quantity" type="number" min="0.1" max="100000" step="any" required></label><button type="submit" class="primary-button">장보기 목록에 추가</button></form><div class="extra-items">${Object.entries(state.extraGroceries[state.week]||{}).map(([id,q])=>`<p>${I[id].name} ${amount(q)}${I[id].unit}<button class="link-button" data-a="remove-extra" data-id="${id}">추가분 삭제</button></p>`).join('')}</div>`);return true;}
 if(a==='remove-extra'){delete state.extraGroceries[state.week][id];state.checked[state.week]={};await save();closeDialog();render();return true;}
 return false;
}
function ingredientOptions(){return `<datalist id="ingredient-options">${Object.values(I).map(i=>`<option value="${i.name}">${i.unit}</option>`).join('')}</datalist>`;}
async function generateSavedWeek(){try{const next=makePlan(state.prefs,state.pantry,Date.now()%997,catalog());state.weeks[state.week]=next;state.checked[state.week]={};selectedDay=null;state.accepted=true;await save();closeDialog();page='week';render();scrollTop();toast('저장한 조건으로 식단을 만들었어요.');}catch(e){toast(e.message);}}
async function featureSubmit(form){
 if(await commerce.submit(form))return;
 const data=new FormData(form);
 if(form.id==='recipe-editor'){
  const d={...editorDraft,...Object.fromEntries(data),servings:Number(data.get('servings')),time:Number(data.get('time')),meals:data.getAll('meals'),tools:data.getAll('tools')};editorDraft=d;
  try{const {ing,issues}=parseIngredientLines(d.ingredientText,d.servings);if(issues.length)throw new Error('재료 이름·수량·단위를 확인해주세요: '+issues.slice(0,5).join(' / '));
   const recipe=validateCustomRecipe({...d,ing,steps:d.stepsText.split('\n').map(s=>s.trim()).filter(Boolean),...Object.fromEntries(['kcal','protein','carbs','fat'].map(k=>[k,data.get(k)===''?null:Number(data.get(k))]))});
   const candidate=state.userRecipes.filter(r=>r.id!==recipe.id);candidate.push(recipe);validateLibrary({...state,userRecipes:candidate});state.userRecipes=candidate;let removed=0;for(const [key,plan]of Object.entries(state.weeks)){state.weeks[key]=plan.map(day=>day.filter(slot=>{const keep=slot.recipe!==recipe.id||allowed(recipe,state.prefs,slot.meal);if(!keep)removed++;return keep;}));}if(!state.saved.includes(recipe.id))state.saved.push(recipe.id);state.checked={};await save();closeDialog();recipeId=recipe.id;recipeSlot=null;recipeReturn='saved';servings=state.prefs.people;page='recipe';render();scrollTop();toast(removed?'레시피를 저장하고 조건에 맞지 않는 기존 끼니 '+removed+'개를 비웠어요.':'레시피를 저장했어요.');
  }catch(e){editorError=e.message;renderRecipeEditor();}
 }
 if(form.id==='recipe-import-form'){const parsed=parseRecipeText(String(data.get('text'))),url=publicRecipeUrl(String(data.get('sourceUrl')||''));editRecipe(null,{id:'own-'+crypto.randomUUID(),servings:1,time:20,meals:['lunch','dinner'],tools:['stove'],kcal:'',protein:'',carbs:'',fat:'',...parsed,sourceUrl:url});}
 if(form.id==='book-form'){if(state.cookbooks.length>=50)throw new Error('요리책은 최대 50개까지 만들 수 있어요.');const name=String(data.get('name')).trim();if(!name||name.length>60)return;const book={id:'book-'+crypto.randomUUID(),name,recipes:page==='recipe'&&recipeId?[recipeId]:[]};state.cookbooks.push(book);await save();closeDialog();if(page==='saved')libraryFilter=book.id;render();toast('요리책을 만들었어요.');}
 if(form.id==='slot-form'){const target={day:Number(data.get('day')),meal:String(data.get('meal'))},id=form.dataset.recipe;if(id){state.weeks[state.week]=setMeal(currentPlan(),target.day,target.meal,id,state.prefs,catalog());state.checked[state.week]={};await save();closeDialog();page='week';selectedDay=null;render();scrollTop();toast('식단과 장보기 목록에 추가했어요.');}else{mealTarget=target;libraryFilter='all';librarySearch='';closeDialog();page='saved';render();scrollTop();}}
 if(form.id==='extra-grocery-form'){const id=ingredientId(String(data.get('ingredient')).trim()),q=Number(data.get('quantity'));if(!id||!Number.isFinite(q)||q<=0||q>100000)throw new Error('등록된 재료 이름과 올바른 수량을 입력해주세요.');state.extraGroceries[state.week]??={};const total=(state.extraGroceries[state.week][id]||0)+q;if(total>100000)throw new Error('추가 수량을 100,000 이하로 입력해주세요.');state.extraGroceries[state.week][id]=total;state.checked[state.week]={};await save();closeDialog();render();toast('장보기 목록에 추가했어요.');}
}
document.addEventListener('submit',e=>{if(['recipe-editor','recipe-import-form','slot-form','book-form','extra-grocery-form','shop-offer-form','shop-settings-form','shop-stores-form'].includes(e.target.id)){e.preventDefault();featureSubmit(e.target).catch(err=>toast(err.message||'저장하지 못했어요.'));}});
document.addEventListener('input',e=>{if(e.target.id==='library-search'){const pos=e.target.selectionStart;librarySearch=e.target.value;render();const input=$('#library-search');input.focus({preventScroll:true});input.setSelectionRange(pos,pos);}});
async function action(el){const a=el.dataset.a,id=el.dataset.id;
if(await commerce.action(el))return;
if(await featureAction(el))return;
if(a==='store'){if(draft.stores.includes(id))draft.stores=draft.stores.filter(x=>x!==id);else if(draft.stores.length<3)draft.stores.push(id);else{toast('마트는 최대 3곳까지 선택할 수 있어요.');return;}draft.store=draft.stores[0]||null;render();}
if(a==='next')goNext();if(a==='back')back();if(a==='restart')resetSetup();
if(a==='household'){draft[el.dataset.field]=Math.max(0,Math.min(8,draft[el.dataset.field]+Number(el.dataset.delta)));render();}
if(a==='multi'){const field=el.dataset.field;draft[field]=draft[field].includes(id)?draft[field].filter(x=>x!==id):[...draft[field],id];error='';if(step===7||step===8)restrictionRender();else render();}
if(a==='day'){const d=Number(id);draft.days=draft.days.includes(d)?draft.days.filter(x=>x!==d):[...draft.days,d];error='';render();}
if(a==='diet'){draft.diet=id;error='';render();}
if(a==='no-allergy'){draft.allergies=[];error='';render();}
if(a==='restriction-category'){if(el.dataset.kind==='allergy')allergyCategory=id;else dislikeCategory=id;restrictionRender();}
if(a==='restriction-clear-search'){const kind=el.dataset.kind;if(kind==='allergy')allergySearch='';else dislikeSearch='';render();$('#'+kind+'-search').focus({preventScroll:true});}
if(a==='restriction-reset'){if(el.dataset.kind==='allergy')draft.allergies=[];else draft.dislikes=[];error='';restrictionRender();}

if(a==='pantry-category'){pantryCategory=id;render();}
if(a==='pantry'){draft.pantry[id]=draft.pantry[id]>0?0:I[id].pack;render();}
if(a==='pantry-amount'){openDialog(`<h2>${I[id].name}</h2><p>보유하고 있는 수량을 입력해주세요.</p><form id="pantry-form" data-id="${id}"><label>수량 (${I[id].unit})<input id="pantry-quantity" type="number" min="0" max="100000" step="any" value="${draft.pantry[id]}" required></label><button type="submit" class="primary-button">수량 저장</button></form>`);}
if(a==='close-dialog')closeDialog();
if(a==='about')await about();
if(a==='policy')await showPolicy(id);
if(a==='resume'){state.accepted=true;if(state.weeks[mondayKey()])state.week=mondayKey();selectedDay=null;page='week';render();scrollTop();}
if(a==='backup'){if(await download(createBackup(state),'밥상-백업-'+new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date())+'.json'))toast('백업 파일을 준비했어요.');}
if(a==='import')$('#import-backup').click();
if(a==='restore'){if(importedState){await writeState('bapsang.v1',JSON.stringify(importedState));state=importedState;importedState=null;closeDialog();resetSetup();toast('백업 데이터를 복원했어요.');}}
if(a==='confirm-delete')openDialog(`<h2>모든 데이터를 지울까요?</h2><p>이 기기의 식단, 냉장고 재료, 알레르기와 보관함을 모두 삭제해요. 직접 저장한 백업 파일은 삭제되지 않아요.</p><button class="primary-button danger-button" data-a="delete-all">모두 삭제</button><button class="cancel-button" data-a="about">취소</button>`);
if(a==='delete-all'){await deleteState('bapsang.v1');location.reload();}

if(a==='generate')await generate();
if(a==='accept'){state.accepted=true;save();page='week';render();scrollTop();}
if(a==='week'){mealTarget=null;page='week';render();scrollTop();}
if(a==='shopping'){page='shopping';render();scrollTop();}
if(a==='saved'){mealTarget=null;page='saved';render();scrollTop();}
if(a==='recipe'){recipeId=id;recipeSlot=el.dataset.day!==undefined?{day:Number(el.dataset.day),index:Number(el.dataset.index)}:null;recipeReturn=page;servings=state.prefs.people;recipeTab='ingredients';convert=false;page='recipe';render();scrollTop();}
if(a==='swap'){try{state.weeks[state.week]=swapRecipe(currentPlan(),Number(el.dataset.day),Number(el.dataset.index),state.prefs,state.pantry,undefined,catalog());state.checked[state.week]={};save();render();toast('메뉴를 바꿨어요. 장보기 목록도 업데이트했어요.');}catch(e){toast(e.message);}}
if(a==='check'){state.checked[state.week]??={};state.checked[state.week][id]=!checked()[id];save();const y=scrollY;render();window.scrollTo(0,y);}
if(a==='recipe-tab'){recipeTab=id;const y=scrollY;render();window.scrollTo(0,y);}
if(a==='servings'){servings=Math.max(.5,Math.min(16,servings+Number(el.dataset.delta)));const y=scrollY;render();window.scrollTo(0,y);}
if(a==='convert'){convert=!convert;const y=scrollY;render();window.scrollTo(0,y);}
if(a==='bookmark'){state.saved=state.saved.includes(recipeId)?state.saved.filter(x=>x!==recipeId):[...state.saved,recipeId];save();const y=scrollY;render();window.scrollTo(0,y);}
if(a==='cooked'){const s=currentPlan()[recipeSlot.day][recipeSlot.index];s.cooked=!s.cooked;save();const y=scrollY;render();window.scrollTo(0,y);}
if(a==='copy')await copyText(textList());if(a==='download'){if(await download())toast(isNativeApp()?'파일 저장·공유 화면을 열었어요.':'목록을 파일로 저장했어요.');}
if(a==='share-recipe'){const r=catalog().find(x=>x.id===recipeId);await shareText('밥상 · '+r.name,`${r.name} · ${amount(servings)}인분\n\n`+Object.entries(r.ing).map(([id,q])=>`${I[id].name} ${amount(q*servings)}${I[id].unit}`).join('\n')+'\n\n'+r.steps.map((s,i)=>`${i+1}. ${s}`).join('\n'));}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-a]');if(el){e.preventDefault();action(el).catch(err=>{console.error(err);toast('처리하지 못했어요. 다시 시도해주세요.');});}});
document.addEventListener('input',e=>{if(e.target.id==='allergy-search'||e.target.id==='dislike-search'){const inputId=e.target.id,pos=e.target.selectionStart;if(inputId==='allergy-search')allergySearch=e.target.value;else dislikeSearch=e.target.value;const y=scrollY;render();const input=$('#'+inputId);input.focus({preventScroll:true});input.setSelectionRange(pos,pos);window.scrollTo(0,y);}if(e.target.id==='pantry-search'){const pos=e.target.selectionStart;pantrySearch=e.target.value;render();$('#pantry-search').focus();$('#pantry-search').setSelectionRange(pos,pos);}if(e.target.id==='budget-range')updateBudget(Number(e.target.value),'range');if(e.target.id==='budget-input')updateBudget(Number(e.target.value.replace(/\D/g,'')),'input');});
document.addEventListener('focusout',e=>{if(e.target.id==='budget-input')e.target.value=draft.budget.toLocaleString('ko-KR');});
document.addEventListener('submit',e=>{if(e.target.id==='pantry-form'){e.preventDefault();const q=Number($('#pantry-quantity').value);if(!Number.isFinite(q)||q<0||q>100000)return;draft.pantry[e.target.dataset.id]=q;closeDialog();render();}});
document.addEventListener('keydown',e=>{const dialog=$('.dialog');if(!dialog)return;if(e.key==='Escape'){closeDialog();return;}if(e.key==='Tab'){const controls=[...dialog.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
const commerce=createCommerce({state:()=>state,groceries:groceryList,checked,weekRange,save,render,toast,openDialog,closeDialog,copy:copyText,footer,bottomNav,native:isNativeApp,visible:()=>page==='shopping'});
render();
commerce.load();

document.addEventListener('change',async e=>{if(e.target.id!=='import-backup')return;try{const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024)throw new Error('5MB 이하의 밥상 백업 파일을 골라주세요.');importedState=parseBackup(await file.text());openDialog(`<h2>백업 데이터를 가져올까요?</h2><p>알레르기 ${importedState.prefs.allergies.length}가지 · 보관한 레시피 ${importedState.saved.length}개<br>현재 설정과 식단을 이 파일의 내용으로 대체합니다.</p><button class="primary-button" data-a="restore">이 데이터로 복원</button><button class="cancel-button" data-a="about">취소</button>`);}catch(e){importedState=null;toast(e.message||'백업을 가져오지 못했어요.');}});
globalThis.BapsangNavigation={back(){if($('.dialog')){closeDialog();return true;}if(page==='setup'&&step===0)return false;if(page==='loading')return true;back();return true;}};
